function PageHeading({ eyebrow, title, copy, action }: { eyebrow: string; title: string; copy: string; action?: React.ReactNode }) {
  return <div className="mb-8 flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><div className="mb-2 font-mono text-[10px] font-medium uppercase tracking-[.22em] text-primary">{eyebrow}</div><h1 className="font-serif text-4xl leading-[1.05] tracking-[-.025em] text-foreground md:text-5xl">{title}</h1><p className="mt-3 max-w-xl text-sm leading-6 text-muted-foreground">{copy}</p></div>{action}</div>;
}

function HomePage({ workspace, update }: { workspace: Workspace; update: (next: Workspace) => void }) {
  const [sessionTopic, setSessionTopic] = useState<Topic | null>(null);
  const recs = recommendations(workspace, 0).slice(0, 3);
  const upcoming = workspace.exams.filter((exam) => !exam.complete).sort((a, b) => a.date.localeCompare(b.date)).slice(0, 3);
  const completedToday = workspace.sessions.filter((session) => session.date === today()).reduce((sum, s) => sum + s.minutes, 0);
  return <><PageHeading eyebrow={dayLabel(today())} title={`Good morning, ${workspace.profile.name}.`} copy="A clear desk for the work that matters next." action={<div className="flex items-center gap-2"><Badge tone="green"><span className="mr-1.5 size-1.5 rounded-full bg-primary" />Local workspace</Badge><Link href="/library" className="hidden sm:inline-flex"><Button data-testid="button-open-library"><FolderOpen size={16} />Open library</Button></Link></div>} />
    <section className="fade-up grid gap-5 xl:grid-cols-[1.35fr_.65fr]"><div className="relative overflow-hidden rounded-2xl bg-primary p-6 text-primary-foreground md:p-8"><div className="absolute -right-12 -top-20 size-64 rounded-full border-[28px] border-primary-foreground/10" /><div className="absolute -bottom-24 right-32 size-48 rounded-full border-[18px] border-sidebar-primary/20" /><div className="relative"><div className="mb-8 flex items-center gap-2 text-xs font-semibold text-primary-foreground/70"><Zap size={15} className="text-sidebar-primary" />YOUR NEXT FOCUS</div>{recs[0] ? <><div className="flex flex-col gap-5 sm:flex-row sm:items-end sm:justify-between"><div><h2 className="max-w-lg font-serif text-3xl leading-tight md:text-4xl">{recs[0].topic.title}</h2><p className="mt-2 text-sm text-primary-foreground/65">{recs[0].course.name} · {recs[0].reason}</p></div><Button className="w-fit bg-sidebar-primary text-sidebar-primary-foreground hover:brightness-105" onClick={() => setSessionTopic(recs[0].topic)} data-testid="button-start-focus"><Clock3 size={16} />Log study</Button></div><div className="mt-8 flex items-center gap-3 border-t border-primary-foreground/15 pt-4 text-xs text-primary-foreground/65"><span className="font-mono text-sidebar-primary">{mins(recs[0].topic.minutes)}</span><span>fits your next available block</span></div></> : <><h2 className="font-serif text-3xl">Your desk is clear.</h2><p className="mt-2 text-primary-foreground/65">Add an exam or topic and i-Buk will help choose the next useful step.</p></>}</div></div><div className="rounded-2xl border border-card-border bg-card p-6"><div className="flex items-start justify-between"><div><div className="font-mono text-[10px] uppercase tracking-[.18em] text-muted-foreground">Today</div><div className="mt-2 font-serif text-3xl">{mins(completedToday)}</div><p className="mt-1 text-sm text-muted-foreground">logged so far</p></div><div className="grid size-11 place-items-center rounded-xl bg-secondary text-primary"><CheckCircle2 size={21} /></div></div><div className="mt-7 h-2 overflow-hidden rounded-full bg-secondary"><div className="h-full rounded-full bg-accent transition-all" style={{ width: `${Math.min(100, Math.round(completedToday / Math.max(1, workspace.availability.dailyMinutes) * 100))}%` }} /></div><div className="mt-2 flex justify-between text-xs text-muted-foreground"><span>Daily intention</span><span>{mins(workspace.availability.dailyMinutes)}</span></div></div></section>
    <div className="mt-8 grid gap-8 xl:grid-cols-[1.35fr_.65fr]"><section className="fade-up-2"><div className="mb-3 flex items-center justify-between"><h2 className="font-serif text-2xl">Suggested for you</h2><Link href="/schedule" className="text-xs font-semibold text-primary hover:underline" data-testid="link-see-schedule">Tune schedule</Link></div><div className="grid gap-3">{recs.length ? recs.map((rec) => <div key={rec.topic.id} className="lift flex items-center gap-4 rounded-xl border border-card-border bg-card p-4"><span className="grid size-9 shrink-0 place-items-center rounded-lg bg-secondary font-mono text-[10px] font-medium text-primary">{String(rec.topic.minutes).padStart(2, '0')}</span><div className="min-w-0 flex-1"><div className="truncate text-sm font-semibold">{rec.topic.title}</div><div className="mt-1 flex flex-wrap items-center gap-2 text-xs text-muted-foreground"><span>{rec.course.code}</span><span className="size-1 rounded-full bg-border" /><span>{rec.reason}</span></div></div><Button variant="ghost" className="shrink-0 p-2" onClick={() => setSessionTopic(rec.topic)} aria-label={`Log ${rec.topic.title}`} data-testid={`button-log-recommendation-${rec.topic.id}`}><Plus size={18} /></Button></div>) : <EmptyState icon={Sparkles} title="Nothing queued yet" copy="Add a course, topic, or exam to create a small, sensible queue." action={<Link href="/library"><Button data-testid="button-add-first-topic"><Plus size={16} />Add a topic</Button></Link>} />}</div></section><section className="fade-up-3"><div className="mb-3 flex items-center justify-between"><h2 className="font-serif text-2xl">On the horizon</h2><Link href="/schedule" className="text-xs font-semibold text-primary hover:underline" data-testid="link-see-exams">View all</Link></div><div className="rounded-2xl border border-card-border bg-card p-4">{upcoming.length ? <div className="grid divide-y divide-border">{upcoming.map((exam) => { const course = workspace.courses.find((c) => c.id === exam.courseId); return <div key={exam.id} className="flex items-center gap-3 py-3 first:pt-1 last:pb-1"><div className="grid size-9 place-items-center rounded-lg bg-[#f3dfc1] text-[#76522d]"><CalendarDays size={16} /></div><div className="min-w-0 flex-1"><div className="truncate text-sm font-semibold">{exam.title}</div><div className="mt-0.5 text-xs text-muted-foreground">{course?.code} · {daysUntil(exam.date) === 1 ? 'tomorrow' : `in ${daysUntil(exam.date)} days`}</div></div><span className="font-mono text-xs text-muted-foreground">{shortDate(exam.date)}</span></div>; })}</div> : <p className="py-6 text-center text-sm text-muted-foreground">No upcoming exams. Enjoy the breathing room.</p>}</div></section></div>
    {sessionTopic && <SessionModal topic={sessionTopic} onClose={() => setSessionTopic(null)} workspace={workspace} update={update} />}
  </>;
}

type Rec = { topic: Topic; course: Course; reason: string; score: number };
function recommendations(workspace: Workspace, dayOffset: number): Rec[] {
  const target = addDays(today(), dayOffset);
  const capacity = workspace.availability.dailyMinutes;
  return workspace.topics.filter((topic) => topic.status !== 'done').map((topic) => {
    const exam = workspace.exams.find((e) => e.courseId === topic.courseId && !e.complete);
    const due = exam ? Math.max(1, daysUntil(exam.date) - dayOffset) : 60;
    const stale = topic.lastStudied ? Math.max(0, daysUntil(target) - daysUntil(topic.lastStudied)) : 14;
    const score = (exam ? Math.max(0, 30 - due * 1.8) : 0) + (topic.lastStudied ? Math.min(18, stale * 1.5) : 20) + (topic.important ? 8 : 0) - Math.max(0, topic.minutes - capacity) * .25;
    const reason = exam && due < 14 ? `${exam.title} in ${due} days` : topic.lastStudied ? `last studied ${Math.max(1, stale)} days ago` : 'not studied yet';
    return { topic, course: workspace.courses.find((course) => course.id === topic.courseId)!, reason, score };
  }).sort((a, b) => b.score - a.score);
}

function SessionModal({ topic, workspace, update, onClose }: { topic: Topic; workspace: Workspace; update: (next: Workspace) => void; onClose: () => void }) {
  const [minutes, setMinutes] = useState(String(topic.minutes));
  const [note, setNote] = useState('');
  const submit = (e: React.FormEvent) => { e.preventDefault(); const n = Number(minutes) || topic.minutes; update({ ...workspace, sessions: [...workspace.sessions, { id: newId('session'), topicId: topic.id, date: today(), minutes: n, note: note.trim() || undefined }], topics: workspace.topics.map((item) => item.id === topic.id ? { ...item, lastStudied: today() } : item) }); onClose(); };
  return <Modal title="Log a study session" description={`${topic.title} · keep it honest, not perfect`} onClose={onClose}><form className="grid gap-4" onSubmit={submit}><Field label="Minutes studied"><TextInput data-testid="input-session-minutes" type="number" min="1" max="600" value={minutes} onChange={(e) => setMinutes(e.target.value)} /></Field><Field label="A quick note" hint="Optional"><TextArea data-testid="input-session-note" value={note} onChange={(e) => setNote(e.target.value)} placeholder="What became clearer?" /></Field><div className="flex justify-end gap-2 pt-2"><Button type="button" variant="ghost" onClick={onClose} data-testid="button-cancel-session">Cancel</Button><Button type="submit" data-testid="button-save-session"><Check size={16} />Save session</Button></div></form></Modal>;
}

function LibraryPage({ workspace, update }: { workspace: Workspace; update: (next: Workspace) => void }) {
  const [courseId, setCourseId] = useState(workspace.courses[0]?.id ?? '');
  const [modal, setModal] = useState<'course' | 'topic' | 'material' | 'session' | null>(null);
  const [editing, setEditing] = useState<Course | Topic | null>(null);
  const [referenceMessage, setReferenceMessage] = useState('');
  const course = workspace.courses.find((item) => item.id === courseId);
  const topics = workspace.topics.filter((topic) => topic.courseId === courseId);
  const materials = workspace.materials.filter((material) => material.courseId === courseId);
  const removeCourse = (item: Course) => { if (window.confirm(`Delete ${item.name} and its topics?`)) { update({ ...workspace, courses: workspace.courses.filter((c) => c.id !== item.id), topics: workspace.topics.filter((t) => t.courseId !== item.id), materials: workspace.materials.filter((m) => m.courseId !== item.id), exams: workspace.exams.filter((e) => e.courseId !== item.id) }); if (courseId === item.id) setCourseId(workspace.courses.find((c) => c.id !== item.id)?.id ?? ''); } };
  return <><PageHeading eyebrow="The library" title="Your courses, in order." copy="A small, dependable index for the things you are actually responsible for." action={<Button onClick={() => { setEditing(null); setModal('course'); }} data-testid="button-add-course"><Plus size={16} />New course</Button>} />
    {!workspace.courses.length ? <EmptyState icon={LibraryBig} title="Your library is waiting" copy="Start with one course. You can add topics and local references as you go." action={<Button onClick={() => setModal('course')} data-testid="button-add-empty-course"><Plus size={16} />Create first course</Button>} /> : <div className="grid gap-6 lg:grid-cols-[280px_1fr]"><section className="grid content-start gap-2">{workspace.courses.map((item) => <button key={item.id} onClick={() => setCourseId(item.id)} data-testid={`button-select-course-${item.id}`} className={`lift group flex items-center gap-3 rounded-xl border p-4 text-left transition ${item.id === courseId ? 'border-primary/40 bg-card shadow-sm' : 'border-transparent bg-card/60 hover:bg-card'}`}><span className="size-3 rounded-full" style={{ backgroundColor: item.color }} /><span className="min-w-0 flex-1"><span className="block font-mono text-[10px] uppercase tracking-wider text-muted-foreground">{item.code}</span><span className="mt-1 block truncate text-sm font-semibold">{item.name}</span></span><ChevronRight size={15} className={`text-muted-foreground transition ${item.id === courseId ? 'text-primary' : 'opacity-0 group-hover:opacity-100'}`} /></button>)}<button className="flex items-center gap-2 rounded-xl border border-dashed border-border px-4 py-3 text-left text-xs font-semibold text-muted-foreground hover:border-primary hover:text-primary" onClick={() => { setEditing(null); setModal('course'); }} data-testid="button-add-another-course"><Plus size={15} />Add another course</button></section>{course ? <section className="min-w-0"><div className="mb-5 flex flex-wrap items-start justify-between gap-3"><div><div className="flex items-center gap-2"><span className="size-2.5 rounded-full" style={{ backgroundColor: course.color }} /><span className="font-mono text-xs text-muted-foreground">{course.code}</span></div><h2 className="mt-1 font-serif text-3xl">{course.name}</h2></div><div className="flex gap-1"><Button variant="ghost" className="p-2" onClick={() => { setEditing(course); setModal('course'); }} aria-label="Edit course" data-testid={`button-edit-course-${course.id}`}><Pencil size={16} /></Button><Button variant="danger" className="p-2" onClick={() => removeCourse(course)} aria-label="Delete course" data-testid={`button-delete-course-${course.id}`}><Trash2 size={16} /></Button></div></div><div className="grid gap-6 xl:grid-cols-[1fr_300px]"><div><div className="mb-3 flex items-center justify-between"><h3 className="font-serif text-xl">Topics <span className="font-sans text-sm text-muted-foreground">({topics.length})</span></h3><Button variant="secondary" onClick={() => setModal('topic')} data-testid="button-add-topic"><Plus size={15} />Add topic</Button></div><div className="overflow-hidden rounded-2xl border border-card-border bg-card"><div className="hidden grid-cols-[1fr_100px_100px_80px] gap-4 border-b border-border bg-muted/50 px-4 py-3 font-mono text-[10px] uppercase tracking-wider text-muted-foreground"><span>Topic</span><span>Last studied</span><span>Length</span><span /></div>{topics.length ? <div className="divide-y divide-border">{topics.filter((t) => !t.parentId).map((topic) => <TopicRow key={topic.id} topic={topic} workspace={workspace} update={update} onEdit={(item) => { setEditing(item); setModal('topic'); }} onSession={(item) => { setEditing(item); setModal('session'); }} />)}</div> : <div className="p-8"><EmptyState icon={ListPlus} title="No topics yet" copy="Break this course into the next few things you can sit down and study." action={<Button onClick={() => setModal('topic')} data-testid="button-add-first-topic"><Plus size={15} />Add topic</Button>} /></div>}</div></div><div><div className="mb-3 flex items-center justify-between"><h3 className="font-serif text-xl">References</h3><Button variant="ghost" className="p-2" onClick={() => setModal('material')} aria-label="Add reference" data-testid="button-add-material"><Plus size={17} /></Button></div>{referenceMessage && <div className="mb-2 rounded-lg bg-muted px-3 py-2 text-xs text-muted-foreground">{referenceMessage}</div>}<div className="rounded-2xl border border-card-border bg-card p-2">{materials.length ? materials.map((material) => <div key={material.id} className="group flex items-start gap-3 rounded-xl p-3 hover:bg-muted"><div className="mt-0.5 grid size-8 shrink-0 place-items-center rounded-lg bg-secondary text-primary">{material.kind === 'file' ? <FolderOpen size={15} /> : <Link2 size={15} />}</div><button className="min-w-0 flex-1 text-left" onClick={async () => { const result = await openMaterialReference(material); setReferenceMessage(result.ok ? 'Opened reference.' : result.message ?? 'Could not open reference.'); }} data-testid={`button-open-material-${material.id}`}><div className="text-sm font-semibold">{material.title}</div><div className="mt-1 truncate font-mono text-[10px] text-muted-foreground">{material.reference}</div></button><Button variant="ghost" className="p-1.5" onClick={async () => { const result = await copyMaterialPath(material.reference); setReferenceMessage(result.ok ? 'Copied reference.' : result.message ?? 'Could not copy reference.'); }} aria-label="Copy reference" data-testid={`button-copy-material-${material.id}`}><Copy size={14} /></Button><button onClick={() => update({ ...workspace, materials: workspace.materials.filter((m) => m.id !== material.id) })} className="p-1 text-muted-foreground opacity-0 hover:text-destructive group-hover:opacity-100" aria-label="Remove reference" data-testid={`button-delete-material-${material.id}`}><Trash2 size={14} /></button></div>) : <div className="p-5 text-center text-sm text-muted-foreground">No references attached yet.</div>}<button className="m-2 flex w-[calc(100%-1rem)] items-center justify-center gap-2 rounded-lg border border-dashed border-border py-2.5 text-xs font-semibold text-muted-foreground hover:border-primary hover:text-primary" onClick={() => setModal('material')} data-testid="button-add-reference"><Plus size={14} />Add local or web reference</button></div></div></div></section> : <EmptyState icon={LibraryBig} title="Choose a course" copy="Select a course to see its topics and references." />}</div>}
    {modal === 'course' && <CourseModal item={editing as Course | null} workspace={workspace} update={update} onClose={() => setModal(null)} onCreated={(id) => setCourseId(id)} />}
    {modal === 'topic' && <TopicModal item={editing as Topic | null} courseId={courseId} workspace={workspace} update={update} onClose={() => setModal(null)} />}
    {modal === 'material' && <MaterialModal courseId={courseId} workspace={workspace} update={update} onClose={() => setModal(null)} />}
    {modal === 'session' && <SessionModal topic={editing as Topic} workspace={workspace} update={update} onClose={() => setModal(null)} />}
  </>;
}
function TopicRow({ topic, workspace, update, onEdit, onSession, depth = 0 }: { topic: Topic; workspace: Workspace; update: (next: Workspace) => void; onEdit: (item: Topic) => void; onSession: (item: Topic) => void; depth?: number }) {
  const [open, setOpen] = useState(true);
  const childrenTopics = workspace.topics.filter((item) => item.parentId === topic.id);
  const descendants = (rootId: string): string[] => workspace.topics.filter((item) => item.parentId === rootId).flatMap((item) => [item.id, ...descendants(item.id)]);
  const remove = () => { if (window.confirm(`Delete ${topic.title} and its nested topics?`)) { const removed = new Set([topic.id, ...descendants(topic.id)]); update({ ...workspace, topics: workspace.topics.filter((item) => !removed.has(item.id)) }); } };
  return <><div className="group grid items-center gap-3 px-4 py-3.5 sm:grid-cols-[1fr_100px_100px_80px] sm:gap-4" style={{ paddingLeft: `${16 + depth * 24}px` }}><div className="flex min-w-0 items-center gap-2">{childrenTopics.length > 0 && <button className="p-1 text-muted-foreground" onClick={() => setOpen(!open)} aria-label="Toggle nested topics" data-testid={`button-toggle-topic-${topic.id}`}>{open ? <ChevronDown size={14} /> : <ChevronRight size={14} />}</button>}<span className={`size-2 shrink-0 rounded-full ${topic.status === 'done' ? 'bg-primary' : 'bg-accent'}`} /><span className={`truncate text-sm font-semibold ${topic.status === 'done' ? 'text-muted-foreground line-through' : ''}`}>{topic.title}</span>{topic.important && <Badge tone="warm">important</Badge>}</div><div className="hidden text-xs text-muted-foreground sm:block">{topic.lastStudied ? shortDate(topic.lastStudied) : 'Not yet'}</div><div className="hidden font-mono text-xs text-muted-foreground sm:block">{mins(topic.minutes)}</div><div className="flex justify-end gap-0.5 opacity-100 sm:opacity-0 sm:group-hover:opacity-100"><Button variant="ghost" className="p-1.5" onClick={() => onSession(topic)} aria-label="Log study session" data-testid={`button-log-topic-${topic.id}`}><Clock3 size={14} /></Button><Button variant="ghost" className="p-1.5" onClick={() => onEdit(topic)} aria-label="Edit topic" data-testid={`button-edit-topic-${topic.id}`}><Pencil size={14} /></Button><Button variant="danger" className="p-1.5" onClick={remove} aria-label="Delete topic" data-testid={`button-delete-topic-${topic.id}`}><Trash2 size={14} /></Button></div></div>{open && childrenTopics.map((child) => <TopicRow key={child.id} topic={child} depth={depth + 1} workspace={workspace} update={update} onEdit={onEdit} onSession={onSession} />)}</>;
}

function CourseModal({ item, workspace, update, onClose, onCreated }: { item: Course | null; workspace: Workspace; update: (next: Workspace) => void; onClose: () => void; onCreated: (id: string) => void }) {
  const [code, setCode] = useState(item?.code ?? ''); const [name, setName] = useState(item?.name ?? ''); const [color, setColor] = useState(item?.color ?? '#d5835d');
  const submit = (e: React.FormEvent) => { e.preventDefault(); if (!name.trim()) return; if (item) update({ ...workspace, courses: workspace.courses.map((c) => c.id === item.id ? { ...c, code: code.trim() || 'COURSE', name: name.trim(), color } : c) }); else { const created = { id: newId('course'), code: code.trim() || 'COURSE', name: name.trim(), color }; update({ ...workspace, courses: [...workspace.courses, created] }); onCreated(created.id); } onClose(); };
  return <Modal title={item ? 'Edit course' : 'Add a course'} description="Keep the label useful at a glance." onClose={onClose}><form className="grid gap-4" onSubmit={submit}><div className="grid gap-4 sm:grid-cols-[1fr_2fr]"><Field label="Course code"><TextInput data-testid="input-course-code" value={code} onChange={(e) => setCode(e.target.value)} placeholder="PSY 204" /></Field><Field label="Course name"><TextInput data-testid="input-course-name" value={name} onChange={(e) => setName(e.target.value)} placeholder="Cognitive Psychology" /></Field></div><Field label="Course marker"><div className="flex gap-2">{['#d5835d', '#2e7467', '#b99352', '#6d789d', '#bb6871'].map((swatch) => <button type="button" key={swatch} onClick={() => setColor(swatch)} className={`size-9 rounded-full border-2 ${color === swatch ? 'border-foreground' : 'border-transparent'}`} style={{ backgroundColor: swatch }} aria-label={`Use ${swatch}`} data-testid={`button-course-color-${swatch.slice(1)}`} />)}</div></Field><div className="flex justify-end gap-2 pt-2"><Button type="button" variant="ghost" onClick={onClose} data-testid="button-cancel-course">Cancel</Button><Button type="submit" data-testid="button-save-course"><Check size={16} />Save course</Button></div></form></Modal>;
}
function TopicModal({ item, courseId, workspace, update, onClose }: { item: Topic | null; courseId: string; workspace: Workspace; update: (next: Workspace) => void; onClose: () => void }) {
  const [title, setTitle] = useState(item?.title ?? ''); const [minutes, setMinutes] = useState(String(item?.minutes ?? 30)); const [parentId, setParentId] = useState(item?.parentId ?? ''); const [important, setImportant] = useState(item?.important ?? false);
  const submit = (e: React.FormEvent) => { e.preventDefault(); if (!title.trim()) return; const next = { id: item?.id ?? newId('topic'), courseId: item?.courseId ?? courseId, parentId: parentId || undefined, title: title.trim(), minutes: Number(minutes) || 30, lastStudied: item?.lastStudied, status: item?.status ?? 'active', important }; update({ ...workspace, topics: item ? workspace.topics.map((t) => t.id === item.id ? next : t) : [...workspace.topics, next] }); onClose(); };
  const descendantIds = new Set<string>();
  const collectDescendants = (id: string) => workspace.topics.filter((topic) => topic.parentId === id).forEach((topic) => { descendantIds.add(topic.id); collectDescendants(topic.id); });
  if (item) collectDescendants(item.id);
  const parents = workspace.topics.filter((topic) => topic.courseId === courseId && topic.id !== item?.id && !descendantIds.has(topic.id));
  return <Modal title={item ? 'Edit topic' : 'Add a topic'} description="Topics are the units the planner can recommend." onClose={onClose}><form className="grid gap-4" onSubmit={submit}><Field label="Topic name"><TextInput autoFocus data-testid="input-topic-title" value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Memory systems" /></Field><div className="grid gap-4 sm:grid-cols-2"><Field label="Realistic length"><TextInput data-testid="input-topic-minutes" type="number" min="5" max="300" value={minutes} onChange={(e) => setMinutes(e.target.value)} /></Field><Field label="Nested under"><select value={parentId} onChange={(e) => setParentId(e.target.value)} data-testid="select-topic-parent" className="h-10 rounded-lg border border-input bg-background px-3 text-sm outline-none focus:border-primary"><option value="">Top-level topic</option>{parents.map((parent) => <option key={parent.id} value={parent.id}>{parent.title}</option>)}</select></Field></div><label className="flex cursor-pointer items-center gap-3 rounded-lg border border-border p-3 text-sm"><input type="checkbox" checked={important} onChange={(e) => setImportant(e.target.checked)} data-testid="checkbox-topic-important" className="size-4 accent-[hsl(var(--primary))]" /><span><span className="block font-semibold">Mark as important</span><span className="text-xs text-muted-foreground">Important topics get a small priority lift, never a replacement for exam urgency.</span></span></label><div className="flex justify-end gap-2 pt-2"><Button type="button" variant="ghost" onClick={onClose} data-testid="button-cancel-topic">Cancel</Button><Button type="submit" data-testid="button-save-topic"><Check size={16} />Save topic</Button></div></form></Modal>;
}
function MaterialModal({ courseId, workspace, update, onClose }: { courseId: string; workspace: Workspace; update: (next: Workspace) => void; onClose: () => void }) {
  const [kind, setKind] = useState<'file' | 'link'>('file'); const [title, setTitle] = useState(''); const [reference, setReference] = useState(''); const [topicId, setTopicId] = useState('');
  const submit = (e: React.FormEvent) => { e.preventDefault(); if (!title.trim() || !reference.trim()) return; update({ ...workspace, materials: [...workspace.materials, { id: newId('material'), courseId, topicId: topicId || undefined, title: title.trim(), kind, reference: reference.trim() }] }); onClose(); };
  return <Modal title="Add a reference" description="i-Buk stores only this pointer. File contents never leave your device." onClose={onClose}><form className="grid gap-4" onSubmit={submit}><div className="grid grid-cols-2 rounded-lg bg-muted p-1"><button type="button" className={`rounded-md py-2 text-sm font-semibold ${kind === 'file' ? 'bg-card shadow-sm' : 'text-muted-foreground'}`} onClick={() => setKind('file')} data-testid="button-reference-file"><FolderOpen size={15} className="mr-1 inline" />Local file</button><button type="button" className={`rounded-md py-2 text-sm font-semibold ${kind === 'link' ? 'bg-card shadow-sm' : 'text-muted-foreground'}`} onClick={() => setKind('link')} data-testid="button-reference-link"><Link2 size={15} className="mr-1 inline" />Web link</button></div><Field label="Label"><TextInput data-testid="input-material-title" value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Week 4 lecture slides" /></Field><Field label={kind === 'file' ? 'Path on this device' : 'URL'} hint={kind === 'file' ? 'Example: ~/Documents/uni/week-4.pdf' : 'Example: https://…'}><TextInput data-testid="input-material-reference" value={reference} onChange={(e) => setReference(e.target.value)} placeholder={kind === 'file' ? '~/Documents/uni/lecture.pdf' : 'https://'} /></Field><Field label="Related topic"><select value={topicId} onChange={(e) => setTopicId(e.target.value)} data-testid="select-material-topic" className="h-10 rounded-lg border border-input bg-background px-3 text-sm outline-none focus:border-primary"><option value="">Course-level reference</option>{workspace.topics.filter((topic) => topic.courseId === courseId).map((topic) => <option key={topic.id} value={topic.id}>{topic.title}</option>)}</select></Field><div className="flex justify-end gap-2 pt-2"><Button type="button" variant="ghost" onClick={onClose} data-testid="button-cancel-material">Cancel</Button><Button type="submit" data-testid="button-save-material"><Check size={16} />Add reference</Button></div></form></Modal>;
}

function SchedulePage({ workspace, update }: { workspace: Workspace; update: (next: Workspace) => void }) {
  const [tab, setTab] = useState(0); const [modal, setModal] = useState(false); const [availability, setAvailability] = useState(false); const [editingExam, setEditingExam] = useState<Exam | null>(null);
  const recs = recommendations(workspace, tab); const exams = workspace.exams.slice().sort((a, b) => a.date.localeCompare(b.date));
  return <><PageHeading eyebrow="The rhythm of the week" title="Make room for what matters." copy="Recommendations use exam timing, topic freshness, and the time you actually have. Importance helps break ties; it never overrules urgency." action={<Button onClick={() => { setEditingExam(null); setModal(true); }} data-testid="button-add-exam"><Plus size={16} />Add exam</Button>} /><div className="grid gap-6 xl:grid-cols-[1fr_340px]"><section><div className="mb-3 flex items-center justify-between"><h2 className="font-serif text-2xl">Upcoming exams</h2><Badge tone="muted">{exams.filter((e) => !e.complete).length} remaining</Badge></div><div className="overflow-hidden rounded-2xl border border-card-border bg-card">{exams.length ? <div className="divide-y divide-border">{exams.map((exam) => { const course = workspace.courses.find((c) => c.id === exam.courseId); const days = daysUntil(exam.date); return <div key={exam.id} className={`flex items-center gap-4 p-4 ${exam.complete ? 'opacity-55' : ''}`}><div className={`grid size-11 shrink-0 place-items-center rounded-xl ${exam.complete ? 'bg-primary/10 text-primary' : days <= 7 ? 'bg-accent/15 text-accent-foreground' : 'bg-secondary text-primary'}`}>{exam.complete ? <Check size={19} /> : <GraduationCap size={19} />}</div><div className="min-w-0 flex-1"><div className={`text-sm font-semibold ${exam.complete ? 'line-through' : ''}`}>{exam.title}</div><div className="mt-1 text-xs text-muted-foreground">{course?.code} · {exam.complete ? 'completed' : days === 0 ? 'today' : days === 1 ? 'tomorrow' : `in ${days} days`}</div></div><span className="hidden font-mono text-xs text-muted-foreground sm:block">{shortDate(exam.date)}{exam.time ? ` · ${exam.time}` : ''}</span><Button variant="ghost" className="p-2" onClick={() => { setEditingExam(exam); setModal(true); }} aria-label="Edit exam" data-testid={`button-edit-exam-${exam.id}`}><Pencil size={14} /></Button><Button variant={exam.complete ? 'ghost' : 'secondary'} className="px-2.5 text-xs" onClick={() => update({ ...workspace, exams: workspace.exams.map((e) => e.id === exam.id ? { ...e, complete: !e.complete } : e) })} data-testid={`button-toggle-exam-${exam.id}`}>{exam.complete ? 'Reopen' : 'Complete'}</Button></div>; })}</div> : <div className="p-4"><EmptyState icon={GraduationCap} title="No exams on the horizon" copy="Add dates so the planner can understand what deserves attention first." action={<Button onClick={() => { setEditingExam(null); setModal(true); }} data-testid="button-add-empty-exam"><Plus size={15} />Add an exam</Button>} /></div>}</div></section><aside className="grid content-start gap-6"><div className="rounded-2xl border border-card-border bg-card p-5"><div className="flex items-start justify-between"><div><h2 className="font-serif text-2xl">Availability</h2><p className="mt-1 text-xs text-muted-foreground">Your realistic study window</p></div><Button variant="ghost" className="p-2" onClick={() => setAvailability(true)} aria-label="Edit availability" data-testid="button-edit-availability"><Pencil size={15} /></Button></div><div className="mt-5 flex items-end gap-2"><span className="font-serif text-3xl">{workspace.availability.dailyMinutes}</span><span className="pb-1 text-sm text-muted-foreground">min / day</span></div><div className="mt-3 text-xs text-muted-foreground">{workspace.availability.start} — {workspace.availability.end}</div><div className="mt-4 flex gap-1.5">{['S', 'M', 'T', 'W', 'T', 'F', 'S'].map((day, index) => <span key={`${day}-${index}`} className={`grid size-7 place-items-center rounded-md font-mono text-[10px] ${workspace.availability.days.includes(index) ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground'}`}>{day}</span>)}</div></div><div className="rounded-2xl bg-[#f3dfc1] p-5 text-[#634a2f]"><div className="flex items-center gap-2 text-xs font-semibold"><Sparkles size={15} />WHY THIS ORDER?</div><p className="mt-3 text-sm leading-6">Exam dates lead. Then i-Buk brings back topics you have not opened recently, while respecting the length of the available block.</p></div></aside></div><section className="mt-8"><div className="mb-3 flex flex-wrap items-center justify-between gap-3"><div><h2 className="font-serif text-2xl">Study recommendations</h2><p className="mt-1 text-sm text-muted-foreground">A deterministic list you can trust and adjust.</p></div><div className="flex rounded-lg bg-muted p-1">{['Today', 'Tomorrow', 'Next 7 days'].map((label, index) => <button key={label} onClick={() => setTab(index)} className={`rounded-md px-3 py-1.5 text-xs font-semibold ${tab === index ? 'bg-card text-foreground shadow-sm' : 'text-muted-foreground'}`} data-testid={`button-recommendation-${index}`}>{label}</button>)}</div></div><div className="grid gap-3 md:grid-cols-2">{recs.slice(0, tab === 2 ? 7 : 4).map((rec, index) => <div key={rec.topic.id} className="lift flex items-center gap-4 rounded-xl border border-card-border bg-card p-4"><span className="font-mono text-xs text-muted-foreground">{String(index + 1).padStart(2, '0')}</span><div className="min-w-0 flex-1"><div className="truncate text-sm font-semibold">{rec.topic.title}</div><div className="mt-1 text-xs text-muted-foreground">{rec.course.code} · {rec.reason}</div></div><span className="font-mono text-xs text-primary">{mins(rec.topic.minutes)}</span></div>)}{!recs.length && <div className="md:col-span-2"><EmptyState icon={CheckCircle2} title="The queue is clear" copy="Complete exams and topics will stay out of the way. Add more when you are ready." /></div>}</div></section>{modal && <ExamModal item={editingExam} workspace={workspace} update={update} onClose={() => setModal(false)} />}{availability && <AvailabilityModal availability={workspace.availability} onClose={() => setAvailability(false)} update={(next) => update({ ...workspace, availability: next })} />}</>;
}
function ExamModal({ item, workspace, update, onClose }: { item: Exam | null; workspace: Workspace; update: (next: Workspace) => void; onClose: () => void }) {
  const [title, setTitle] = useState(item?.title ?? ''); const [courseId, setCourseId] = useState(item?.courseId ?? workspace.courses[0]?.id ?? ''); const [date, setDate] = useState(item?.date ?? addDays(today(), 14)); const [time, setTime] = useState(item?.time ?? '');
  const submit = (e: React.FormEvent) => { e.preventDefault(); if (!title.trim() || !courseId) return; const exam = { id: item?.id ?? newId('exam'), courseId, title: title.trim(), date, time: time || undefined, complete: item?.complete ?? false }; update({ ...workspace, exams: item ? workspace.exams.map((existing) => existing.id === item.id ? exam : existing) : [...workspace.exams, exam] }); onClose(); };
  return <Modal title={item ? 'Edit exam' : 'Add an exam'} description="A date gives the planner a useful horizon." onClose={onClose}><form className="grid gap-4" onSubmit={submit}><Field label="Exam title"><TextInput data-testid="input-exam-title" value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Cognitive Psychology final" /></Field><div className="grid gap-4 sm:grid-cols-2"><Field label="Course"><select value={courseId} onChange={(e) => setCourseId(e.target.value)} data-testid="select-exam-course" className="h-10 rounded-lg border border-input bg-background px-3 text-sm"><option value="">Choose a course</option>{workspace.courses.map((course) => <option key={course.id} value={course.id}>{course.code}</option>)}</select></Field><Field label="Date"><TextInput type="date" data-testid="input-exam-date" value={date} onChange={(e) => setDate(e.target.value)} /></Field></div><Field label="Time" hint="Optional"><TextInput type="time" data-testid="input-exam-time" value={time} onChange={(e) => setTime(e.target.value)} /></Field><div className="flex justify-end gap-2 pt-2"><Button type="button" variant="ghost" onClick={onClose} data-testid="button-cancel-exam">Cancel</Button><Button type="submit" data-testid="button-save-exam"><Check size={16} />{item ? 'Save changes' : 'Save exam'}</Button></div></form></Modal>;
}
function AvailabilityModal({ availability, update, onClose }: { availability: Availability; update: (next: Availability) => void; onClose: () => void }) {
  const [days, setDays] = useState(availability.days); const [start, setStart] = useState(availability.start); const [end, setEnd] = useState(availability.end); const [dailyMinutes, setDailyMinutes] = useState(String(availability.dailyMinutes));
  const submit = (e: React.FormEvent) => { e.preventDefault(); update({ days, start, end, dailyMinutes: Number(dailyMinutes) || 60 }); onClose(); };
  return <Modal title="Set availability" description="Tell the planner what fits a normal day, not an ideal one." onClose={onClose}><form className="grid gap-5" onSubmit={submit}><Field label="Available days"><div className="flex gap-1.5">{['S', 'M', 'T', 'W', 'T', 'F', 'S'].map((label, index) => <button key={`${label}-${index}`} type="button" onClick={() => setDays(days.includes(index) ? days.filter((d) => d !== index) : [...days, index].sort())} className={`grid size-9 place-items-center rounded-lg border text-xs font-semibold ${days.includes(index) ? 'border-primary bg-primary text-primary-foreground' : 'border-border bg-background text-muted-foreground'}`} data-testid={`button-availability-day-${index}`}>{label}</button>)}</div></Field><div className="grid gap-4 sm:grid-cols-2"><Field label="From"><TextInput type="time" value={start} onChange={(e) => setStart(e.target.value)} data-testid="input-availability-start" /></Field><Field label="Until"><TextInput type="time" value={end} onChange={(e) => setEnd(e.target.value)} data-testid="input-availability-end" /></Field></div><Field label="Study intention per day" hint="Recommendations will respect this cap."><TextInput type="number" min="15" max="600" value={dailyMinutes} onChange={(e) => setDailyMinutes(e.target.value)} data-testid="input-availability-minutes" /></Field><div className="flex justify-end gap-2"><Button type="button" variant="ghost" onClick={onClose} data-testid="button-cancel-availability">Cancel</Button><Button type="submit" data-testid="button-save-availability"><Check size={16} />Save availability</Button></div></form></Modal>;
}

function NotesPage({ workspace, update }: { workspace: Workspace; update: (next: Workspace) => void }) {
  const [editing, setEditing] = useState<Note | null>(null); const [open, setOpen] = useState(false);
  const notes = workspace.notes.slice().sort((a, b) => Number(b.pinned) - Number(a.pinned) || b.updatedAt.localeCompare(a.updatedAt));
  const remove = (note: Note) => { if (window.confirm(`Delete “${note.title}”?`)) update({ ...workspace, notes: workspace.notes.filter((item) => item.id !== note.id) }); };
  return <><PageHeading eyebrow="Loose threads" title="Notes that stay close." copy="A lightweight place for questions, reminders, and the small thoughts that make the next session easier." action={<Button onClick={() => { setEditing(null); setOpen(true); }} data-testid="button-add-note"><Plus size={16} />New note</Button>} />{notes.length ? <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{notes.map((note, index) => { const course = workspace.courses.find((item) => item.id === note.courseId); const topic = workspace.topics.find((item) => item.id === note.topicId); return <article key={note.id} className={`lift fade-up-${Math.min(index + 1, 3)} relative flex min-h-[190px] flex-col rounded-2xl border border-card-border bg-card p-5`}><div className="mb-4 flex items-start justify-between gap-3"><div className="flex items-center gap-2">{note.pinned && <Pin size={14} className="rotate-45 text-accent" />}<span className="font-mono text-[10px] uppercase tracking-[.16em] text-muted-foreground">{note.reminder ? `Reminder · ${shortDate(note.reminder.slice(0, 10))}` : 'Note'}</span></div><div className="flex gap-0.5"><Button variant="ghost" className="p-1.5" onClick={() => { setEditing(note); setOpen(true); }} aria-label="Edit note" data-testid={`button-edit-note-${note.id}`}><Pencil size={14} /></Button><Button variant="danger" className="p-1.5" onClick={() => remove(note)} aria-label="Delete note" data-testid={`button-delete-note-${note.id}`}><Trash2 size={14} /></Button></div></div><h2 className="font-serif text-2xl leading-tight">{note.title}</h2><p className="mt-3 flex-1 whitespace-pre-wrap text-sm leading-6 text-muted-foreground">{note.body}</p>{(course || topic) && <div className="mt-4 text-xs text-primary">{course?.code}{course && topic ? ' · ' : ''}{topic?.title}</div>}<div className="mt-5 border-t border-border pt-3 font-mono text-[10px] text-muted-foreground">Updated {shortDate(note.updatedAt.slice(0, 10))}</div></article>; })}</div> : <EmptyState icon={FileText} title="A blank page, for now" copy="Capture a question before it disappears, or add a reminder for a future study block." action={<Button onClick={() => setOpen(true)} data-testid="button-add-empty-note"><Plus size={15} />Write a note</Button>} />}{open && <NoteModal item={editing} workspace={workspace} update={update} onClose={() => setOpen(false)} />}</>;
}
function NoteModal({ item, workspace, update, onClose }: { item: Note | null; workspace: Workspace; update: (next: Workspace) => void; onClose: () => void }) {
  const [title, setTitle] = useState(item?.title ?? ''); const [body, setBody] = useState(item?.body ?? ''); const [reminder, setReminder] = useState(item?.reminder ?? ''); const [courseId, setCourseId] = useState(item?.courseId ?? ''); const [topicId, setTopicId] = useState(item?.topicId ?? ''); const [pinned, setPinned] = useState(item?.pinned ?? false);
  const submit = (e: React.FormEvent) => { e.preventDefault(); if (!title.trim() || !body.trim()) return; const note = { id: item?.id ?? newId('note'), title: title.trim(), body: body.trim(), reminder: reminder || undefined, courseId: courseId || undefined, topicId: topicId || undefined, pinned, updatedAt: new Date().toISOString() }; update({ ...workspace, notes: item ? workspace.notes.map((n) => n.id === item.id ? note : n) : [...workspace.notes, note] }); onClose(); };
  return <Modal title={item ? 'Edit note' : 'New note'} description="Short is fine. Specific is better." onClose={onClose}><form className="grid gap-4" onSubmit={submit}><Field label="Title"><TextInput autoFocus data-testid="input-note-title" value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Question to bring to seminar" /></Field><Field label="Note"><TextArea className="min-h-32" data-testid="input-note-body" value={body} onChange={(e) => setBody(e.target.value)} placeholder="Write the useful bit…" /></Field><div className="grid gap-4 sm:grid-cols-2"><Field label="Reminder" hint="Optional"><TextInput type="datetime-local" data-testid="input-note-reminder" value={reminder} onChange={(e) => setReminder(e.target.value)} /></Field><Field label="Related to" hint="Optional"><select value={topicId || courseId} onChange={(e) => { const value = e.target.value; if (value.startsWith('topic-')) { setTopicId(value); setCourseId(workspace.topics.find((topic) => topic.id === value)?.courseId ?? ''); } else { setCourseId(value); setTopicId(''); } }} data-testid="select-note-related" className="h-10 rounded-lg border border-input bg-background px-3 text-sm"><option value="">No course or topic</option>{workspace.courses.map((course) => <optgroup key={course.id} label={course.code}>{workspace.topics.filter((topic) => topic.courseId === course.id).map((topic) => <option key={topic.id} value={topic.id}>{topic.title}</option>)}</optgroup>)}</select></Field></div><label className="flex items-center gap-2 text-sm font-semibold"><input type="checkbox" checked={pinned} onChange={(e) => setPinned(e.target.checked)} data-testid="checkbox-note-pinned" className="size-4 accent-[hsl(var(--primary))]" />Keep at top</label><div className="flex justify-end gap-2 pt-2"><Button type="button" variant="ghost" onClick={onClose} data-testid="button-cancel-note">Cancel</Button><Button type="submit" data-testid="button-save-note"><Check size={16} />Save note</Button></div></form></Modal>;
}

function StatsPage({ workspace }: { workspace: Workspace }) {
  const total = workspace.sessions.reduce((sum, session) => sum + session.minutes, 0); const thisWeek = workspace.sessions.filter((s) => daysUntil(s.date) >= -6).reduce((sum, s) => sum + s.minutes, 0); const studied = new Set(workspace.sessions.map((s) => s.topicId)).size; const active = workspace.topics.filter((t) => t.status !== 'done').length; const days = Array.from({ length: 7 }, (_, index) => addDays(today(), index - 6)); const max = Math.max(1, ...days.map((day) => workspace.sessions.filter((s) => s.date === day).reduce((sum, s) => sum + s.minutes, 0)));
  return <><PageHeading eyebrow="A little perspective" title="Progress, without the pressure." copy="A simple record of time you chose to spend. No streaks, no scores — just a clearer view of your work." action={<Badge tone="green"><TrendingUp size={13} className="mr-1" />Local activity</Badge>} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Study time" value={mins(total)} detail="all logged sessions" icon={Clock3} /><Metric label="This week" value={mins(thisWeek)} detail="last 7 days" icon={TrendingUp} /><Metric label="Topics opened" value={`${studied} / ${studied + active}`} detail="have a study history" icon={BookOpen} /><Metric label="Sessions" value={String(workspace.sessions.length)} detail="kept in this workspace" icon={CheckCircle2} /></div><div className="mt-6 grid gap-6 lg:grid-cols-[1.3fr_.7fr]"><section className="rounded-2xl border border-card-border bg-card p-6"><div className="flex items-start justify-between"><div><h2 className="font-serif text-2xl">Activity this week</h2><p className="mt-1 text-sm text-muted-foreground">Minutes logged, by day.</p></div><span className="font-mono text-xs text-muted-foreground">{mins(thisWeek)}</span></div><div className="mt-8 flex h-48 items-end justify-between gap-2 border-b border-border pb-0">{days.map((day) => { const value = workspace.sessions.filter((s) => s.date === day).reduce((sum, s) => sum + s.minutes, 0); return <div key={day} className="flex h-full flex-1 flex-col items-center justify-end gap-2"><span className="font-mono text-[10px] text-muted-foreground">{value || ''}</span><div className="w-full max-w-12 rounded-t-md bg-primary/80 transition-all hover:bg-primary" style={{ height: `${Math.max(value ? 10 : 2, value / max * 75)}%` }} /><span className={`pb-2 font-mono text-[10px] ${day === today() ? 'font-bold text-primary' : 'text-muted-foreground'}`}>{new Intl.DateTimeFormat('en', { weekday: 'short' }).format(new Date(`${day}T12:00:00`)).slice(0, 2)}</span></div>; })}</div></section><section className="rounded-2xl border border-card-border bg-card p-6"><h2 className="font-serif text-2xl">Recently studied</h2><div className="mt-5 grid gap-3">{workspace.sessions.slice().sort((a, b) => b.date.localeCompare(a.date)).slice(0, 5).map((session) => { const topic = workspace.topics.find((t) => t.id === session.topicId); return <div key={session.id} className="flex items-center gap-3"><span className="grid size-8 place-items-center rounded-lg bg-secondary text-primary"><Check size={14} /></span><div className="min-w-0 flex-1"><div className="truncate text-sm font-semibold">{topic?.title ?? 'Removed topic'}</div><div className="text-xs text-muted-foreground">{shortDate(session.date)}</div></div><span className="font-mono text-xs text-muted-foreground">{mins(session.minutes)}</span></div>; })}</div></section></div></>;
}
function Metric({ label, value, detail, icon: Icon }: { label: string; value: string; detail: string; icon: typeof Clock3 }) { return <div className="rounded-2xl border border-card-border bg-card p-5"><div className="flex items-center justify-between"><span className="text-xs font-semibold text-muted-foreground">{label}</span><Icon size={17} className="text-primary" /></div><div className="mt-4 font-serif text-3xl">{value}</div><div className="mt-1 text-xs text-muted-foreground">{detail}</div></div>; }

function SettingsPage({ workspace, update }: { workspace: Workspace; update: (next: Workspace) => void }) {
  const fileInput = useRef<HTMLInputElement>(null); const [name, setName] = useState(workspace.profile.name); const [saved, setSaved] = useState(false);
  const saveName = () => { update({ ...workspace, profile: { name: name.trim() || 'Student' } }); setSaved(true); window.setTimeout(() => setSaved(false), 1800); };
  const exportData = () => { const blob = new Blob([JSON.stringify(workspace, null, 2)], { type: 'application/json' }); const url = URL.createObjectURL(blob); const anchor = document.createElement('a'); anchor.href = url; anchor.download = `ibuk-workspace-${today()}.json`; anchor.click(); URL.revokeObjectURL(url); };
  const importData = async (event: React.ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file) return; try { const imported = JSON.parse(await file.text()) as Workspace; if (!imported.courses || !imported.topics || !imported.exams) throw new Error('Missing workspace fields'); update({ ...imported, version: 1 }); } catch { window.alert('That file does not look like an i-Buk workspace export.'); } event.target.value = ''; };
  const reset = () => { if (window.confirm('Replace this workspace with the starter sample?')) update(sampleWorkspace()); };
  return <><PageHeading eyebrow="Your desk, your rules" title="Settings" copy="i-Buk is deliberately small: local data, clear boundaries, and no account required." /><div className="grid gap-6 lg:grid-cols-[1fr_330px]"><div className="grid gap-5"><section className="rounded-2xl border border-card-border bg-card p-6"><div className="mb-5"><h2 className="font-serif text-2xl">Profile</h2><p className="mt-1 text-sm text-muted-foreground">Just enough personalization to make Today feel like yours.</p></div><div className="flex max-w-lg items-end gap-3"><Field label="Your name" hint="Used in the Today greeting."><TextInput data-testid="input-profile-name" value={name} onChange={(e) => setName(e.target.value)} /></Field><Button onClick={saveName} data-testid="button-save-profile">{saved ? <Check size={16} /> : null}{saved ? 'Saved' : 'Save'}</Button></div></section><section className="rounded-2xl border border-card-border bg-card p-6"><div className="mb-5"><h2 className="font-serif text-2xl">Local data</h2><p className="mt-1 text-sm text-muted-foreground">Move a structured copy between devices. References remain paths and URLs — never file bytes.</p></div><div className="grid gap-3 sm:grid-cols-2"><Button variant="secondary" className="justify-start" onClick={exportData} data-testid="button-export-data"><ArrowDownToLine size={17} /><span><span className="block text-left">Export workspace</span><span className="block text-left text-[11px] font-normal opacity-65">Download JSON</span></span></Button><Button variant="secondary" className="justify-start" onClick={() => fileInput.current?.click()} data-testid="button-import-data"><ArrowUpFromLine size={17} /><span><span className="block text-left">Import workspace</span><span className="block text-left text-[11px] font-normal opacity-65">Restore JSON</span></span></Button><input ref={fileInput} type="file" accept="application/json,.json" onChange={importData} className="hidden" data-testid="input-import-file" /></div></section><section className="rounded-2xl border border-destructive/20 bg-destructive/5 p-6"><div className="flex items-start justify-between gap-4"><div><h2 className="font-serif text-2xl">Start over</h2><p className="mt-1 text-sm text-muted-foreground">Reset this device to the editable sample workspace. This cannot be undone.</p></div><Button variant="danger" onClick={reset} data-testid="button-reset-workspace"><RotateCcw size={16} />Reset</Button></div></section></div><aside className="grid content-start gap-5"><section className="rounded-2xl bg-primary p-6 text-primary-foreground"><div className="flex items-center gap-2 text-xs font-semibold text-sidebar-primary"><span className="size-2 rounded-full bg-sidebar-primary" />LOCAL ONLY</div><h2 className="mt-4 font-serif text-2xl">Private by default.</h2><p className="mt-3 text-sm leading-6 text-primary-foreground/70">Your courses, notes, sessions, and references are saved in this browser’s local storage.</p><div className="mt-5 border-t border-primary-foreground/15 pt-4 text-xs text-primary-foreground/60">No file uploads. No account. No background sync.</div></section><section className="rounded-2xl border border-card-border bg-card p-6"><h2 className="font-serif text-2xl">Integrations</h2><div className="mt-4 grid gap-3"><div className="flex items-center gap-3 rounded-xl bg-muted p-3"><div className="grid size-8 place-items-center rounded-lg bg-secondary text-primary"><Sparkles size={15} /></div><div className="flex-1"><div className="text-sm font-semibold">Optional AI</div><div className="text-xs text-muted-foreground">Not connected</div></div><Badge tone="muted">Unavailable</Badge></div><div className="flex items-center gap-3 rounded-xl bg-muted p-3"><div className="grid size-8 place-items-center rounded-lg bg-secondary text-primary"><RotateCcw size={15} /></div><div className="flex-1"><div className="text-sm font-semibold">Cloud sync</div><div className="text-xs text-muted-foreground">Not connected</div></div><Badge tone="muted">Unavailable</Badge></div></div><p className="mt-4 flex gap-2 text-xs leading-5 text-muted-foreground"><CircleHelp size={14} className="mt-0.5 shrink-0" />The planner works fully without either integration.</p></section></aside></div></>;
}

function AppContent() {
  const [workspace, setWorkspace] = useState<Workspace>(() => loadWorkspace());
  const update = (next: Workspace) => { setWorkspace(next); saveWorkspace(next); };
  return <Shell workspace={workspace}><Switch><Route path="/"><HomePage workspace={workspace} update={update} /></Route><Route path="/library"><LibraryPage workspace={workspace} update={update} /></Route><Route path="/schedule"><SchedulePage workspace={workspace} update={update} /></Route><Route path="/notes"><NotesPage workspace={workspace} update={update} /></Route><Route path="/stats"><StatsPage workspace={workspace} /></Route><Route path="/settings"><SettingsPage workspace={workspace} update={update} /></Route><Route component={NotFound} /></Switch></Shell>;
}
function App() { return <WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><ErrorBoundary resetKey={window.location.pathname}><AppContent /></ErrorBoundary></WouterRouter>; }
export default App;